import{_ as i,o as t,c as n,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Designing a Multitenancy File System for Cloud Environment | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Designing a Multitenancy File System for Cloud Environment | Ceph Days NYC 2024","date":"2024-05-23T00:00:00.000Z","updated":"2024-05-23T00:00:00.000Z","tags":["Ceph","Multi","tenancy","Cloud Storage","Data Security","Automation"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Designing_a_Multitenancy_File_System_for_Cloud_Environment_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Designing_a_Multitenancy_File_System_for_Cloud_Environment_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Designing_a_Multitenancy_File_System_for_Cloud_Environment_Ceph_Days_NYC_2024.md"};function s(r,l,a,_,p,g){return t(),n("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> 利用开源分布式存储系统Ceph为云环境构建多租户文件系统</p><p><strong>主讲人：</strong> Mitch Hall（45 Drives首席架构师）、Brett KY（45 Drives技术总监）</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>项目背景与需求：</strong></p><ul><li>一家《财富》100强公司寻求构建一个用于远程编辑和存储媒体娱乐内容的新云解决方案。</li><li>需求包括多租户支持、存储分层（HDD和SSD）、弹性扩展、数据加密、自动化管理以及支持NFS、SMB、快照和配额等功能。</li></ul></li><li><p><strong>主要挑战：</strong></p><ul><li><strong>可扩展性：</strong> 支持数百至数千个多租户工作站。</li><li><strong>多租户支持：</strong> 实现文件系统的多租户兼容性。</li><li><strong>数据加密：</strong> 实现数据的静态加密。</li><li><strong>自动化：</strong> 开发自动化工具。</li><li><strong>文件系统支持：</strong> 支持多种文件系统功能。</li></ul></li><li><p><strong>硬件与软件选择：</strong></p><ul><li>硬件：45 Drives提供的存储节点和计算节点，每个存储节点配备30个硬盘槽和22个SSD槽。</li><li>软件：Rocky Linux作为操作系统，Ceph Octopus作为分布式存储系统，Proxmox v7.1用于虚拟化。</li></ul></li><li><p><strong>数据隔离与安全：</strong></p><ul><li>使用Ceph的RADOS命名空间实现数据隔离。</li><li>通过配置密钥环限制租户访问权限。</li></ul></li><li><p><strong>加密与自动化：</strong></p><ul><li>使用DM-Crypt和自加密驱动器实现数据加密。</li><li>开发自动化脚本和udev规则。</li></ul></li><li><p><strong>性能测试：</strong></p><ul><li>使用Filebench进行多种性能测试，包括随机读写、顺序读写和小文件操作。</li><li>测试结果显示，虚拟化网关在处理随机IO时性能稳定。</li></ul></li><li><p><strong>部署与挑战：</strong></p><ul><li>在英国的数据中心实际部署时，发现网络配置与预期不符，通过现场调整代码解决了问题。</li></ul></li><li><p><strong>未来计划：</strong></p><ul><li>将虚拟化层替换为容器化。</li><li>改进多MDS管理，实现更自动化的MDS分配和扩展。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>优化自动化工具和配置管理。</li><li>探索容器化解决方案。</li><li>完善MDS管理策略。</li></ul><p><strong>备注：</strong></p><ul><li>会议中提到的技术细节和工具包括Ceph、Rocky Linux、Proxmox、Samba、Ansible、Terraform等。</li></ul>',9)])])}const d=i(o,[["render",s]]);export{c as __pageData,d as default};
